package dev.wordrush.game;

import java.util.UUID;

/**
 * A guess from a client. {@code guessId} is generated by the client per guess and reused on
 * retries, which makes submission idempotent. {@code roundId} stops a slow guess from landing
 * in the next round.
 */
public record GuessRequest(UUID guessId, UUID roundId, String word) {
}
